do $rls$
begin
  execute 'alter table action_def enable row level security';
  execute 'alter table recipe enable row level security';
  execute 'alter table recipe_input enable row level security';
  execute 'alter table recipe_gives enable row level security';
end $rls$;
drop policy if exists action_def_read on action_def;
create policy action_def_read on action_def for select to anon, authenticated using (true);
grant select on action_def to anon, authenticated;
revoke insert, update, delete on action_def from anon, authenticated;
drop policy if exists recipe_read on recipe;
create policy recipe_read on recipe for select to anon, authenticated using (true);
grant select on recipe to anon, authenticated;
